+import freemarker.template.Template;
+import freemarker.template.TemplateException;
+import freemarker.template.TemplateExceptionHandler;
+
+import org.apache.commons.lang3.StringUtils;
+
+import java.io.IOException;
+import java.io.StringReader;
+import java.io.StringWriter;
+import java.util.HashMap;
+import java.util.Map;
+
+public class TemplateService {
+
+    private final Configuration configuration;
+
+    public TemplateService() {
+        configuration = new Configuration(Configuration.VERSION_2_3_31);
+        configuration.setDefaultEncoding("UTF-8");
+        configuration.setTemplateExceptionHandler(TemplateExceptionHandler.RETHROW_HANDLER);
+        configuration.setLogTemplateExceptions(false);
+
+        // Prevent Server-Side Template Injection (SSTI)
+        // Disallow all class instantiation via ?new built-in
+        configuration.setNewBuiltinClassResolver(TemplateClassResolver.ALLOWS_NOTHING_RESOLVER);
+        // Disable the ?api built-in which could expose Java object methods
+        configuration.setAPIBuiltinEnabled(false);
+    }
+
+    public String renderUserProfile(String username, String templateContent) {
+        if (StringUtils.isBlank(templateContent)) {
+            return "";
+        }
+
+        try {
+            // HTML-escape the username to prevent XSS when rendered in HTML context
+            String safeUsername = escapeHtml(username);
+
+            Template template = new Template("userProfile", new StringReader(templateContent), configuration);
+
+            Map<String, Object> dataModel = new HashMap<>();
+            dataModel.put("username", safeUsername);
+
+            StringWriter writer = new StringWriter();
+            template.process(dataModel, writer);
+            return writer.toString();
+        } catch (IOException | TemplateException e) {
+            throw new RuntimeException("Failed to render user profile template", e);
+        }
+    }
+
+    private static String escapeHtml(String input) {
+        if (input == null) {
+            return "";
+        }
+        return StringUtils.replaceEach(
+                input,
+                new String[]{"&", "<", ">", "\"", "'"},
+                new String[]{"&amp;", "&lt;", "&gt;", "&quot;", "&#39;"}
+        );
+    }
+}

